import{_ as i,o as t,c as r,ag as e}from"./chunks/framework.DzGOF12C.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 음양가 (추연)","slug":"_1-음양가-추연","link":"#_1-음양가-추연","children":[{"level":3,"title":"음과 양의 개념 및 확장","slug":"음과-양의-개념-및-확장","link":"#음과-양의-개념-및-확장","children":[]},{"level":3,"title":"천인감응우주론","slug":"천인감응우주론","link":"#천인감응우주론","children":[]},{"level":3,"title":"음양소식","slug":"음양소식","link":"#음양소식","children":[]},{"level":3,"title":"오행과 음양의 결합","slug":"오행과-음양의-결합","link":"#오행과-음양의-결합","children":[]},{"level":3,"title":"오덕종시설","slug":"오덕종시설","link":"#오덕종시설","children":[]}]},{"level":2,"title":"2. 명가 (공손룡)","slug":"_2-명가-공손룡","link":"#_2-명가-공손룡","children":[{"level":3,"title":"명가의 사회적 배경 및 역할 (추정)","slug":"명가의-사회적-배경-및-역할-추정","link":"#명가의-사회적-배경-및-역할-추정","children":[]},{"level":3,"title":"백마론 (흰말은 말이 아니다)","slug":"백마론-흰말은-말이-아니다","link":"#백마론-흰말은-말이-아니다","children":[]},{"level":3,"title":"견백론 (단단함과 흼의 분리)","slug":"견백론-단단함과-흼의-분리","link":"#견백론-단단함과-흼의-분리","children":[]},{"level":3,"title":"통변론 (관계어의 분석)","slug":"통변론-관계어의-분석","link":"#통변론-관계어의-분석","children":[]},{"level":3,"title":"지물론 (사물과 지시)","slug":"지물론-사물과-지시","link":"#지물론-사물과-지시","children":[]}]}],"relativePath":"philosophy/China/06. 음양가와 명가.md","filePath":"philosophy/China/06. 음양가와 명가.md"}'),n={name:"philosophy/China/06. 음양가와 명가.md"};function o(a,l,s,g,h,u){return t(),r("div",null,[...l[0]||(l[0]=[e('<h2 id="_1-음양가-추연" tabindex="-1">1. 음양가 (추연) <a class="header-anchor" href="#_1-음양가-추연" aria-label="Permalink to &quot;1. 음양가 (추연)&quot;">​</a></h2><h3 id="음과-양의-개념-및-확장" tabindex="-1">음과 양의 개념 및 확장 <a class="header-anchor" href="#음과-양의-개념-및-확장" aria-label="Permalink to &quot;음과 양의 개념 및 확장&quot;">​</a></h3><ul><li><strong>기원의 인식:</strong> 해가 드는 것을 &#39;양&#39;, 그늘을 &#39;음&#39;으로 봄. 기의 흐름을 음과 양으로 나눔.</li><li><strong>자연세계 설명:</strong> 이를 확장하여 낮을 &#39;양&#39;, 밤을 &#39;음&#39;으로 설명하듯 자연세계를 설명함.</li><li><strong>인간세계 설명:</strong> 이를 다시 인간세계까지 확장하여 설명함.</li><li><strong>공존과 균형:</strong> 음과 양은 분리된 개념이지만, 서로 공존과 균형을 이루며 세계를 구성함.</li></ul><h3 id="천인감응우주론" tabindex="-1">천인감응우주론 <a class="header-anchor" href="#천인감응우주론" aria-label="Permalink to &quot;천인감응우주론&quot;">​</a></h3><ul><li><strong>개념:</strong> 하늘과 인간이 서로 감응한다는 이론.</li><li><strong>예시:</strong> 오랜 기간 비가 오지 않는 현상은 군주가 올바른 정치를 하지 못했기 때문에 발생함.</li><li><strong>목적:</strong> 혼란스러운 인간세계를 자연을 통해 설명하고자 함.</li></ul><h3 id="음양소식" tabindex="-1">음양소식 <a class="header-anchor" href="#음양소식" aria-label="Permalink to &quot;음양소식&quot;">​</a></h3><ul><li><strong>개념:</strong> 음과 양이 줄어들고 늘어나는 현상.</li><li><strong>현상 설명:</strong> 춘하추동 4계절의 교체는 음과 양의 추이로 이루어지며, 낮과 밤이 바뀌는 것도 음양이 적절하게 작용하는 것임.</li></ul><h3 id="오행과-음양의-결합" tabindex="-1">오행과 음양의 결합 <a class="header-anchor" href="#오행과-음양의-결합" aria-label="Permalink to &quot;오행과 음양의 결합&quot;">​</a></h3><ul><li><strong>본래의 성격:</strong> 본래는 별개의 개념이었음. 음양은 양지와 음지를 의미했고, 오행은 농업과 관련된 5종의 재료를 의미함.</li><li><strong>우주론적 발전:</strong> 오행은 점차 한 세트로 묶이며 우주론적 운행의 의미를 지니게 됨.</li><li><strong>원형이정의 순환 원리:</strong><ul><li><strong>봄:</strong> 소양 – 나무 (목)</li><li><strong>여름:</strong> 태양 – 불 (화)</li><li><strong>가을:</strong> 소음 – 금 (금)</li><li><strong>겨울:</strong> 태음 – 북 (수)</li></ul></li></ul><h3 id="오덕종시설" tabindex="-1">오덕종시설 <a class="header-anchor" href="#오덕종시설" aria-label="Permalink to &quot;오덕종시설&quot;">​</a></h3><ul><li><strong>개념:</strong> 오덕(목·화·토·금·수)이 끝났다 시작했다를 반복한다는 이론.</li><li><strong>왕조 교체 설명:</strong> 왕조의 흥망은 단순한 인간사의 우연이 아니라 오행의 순환에 따라 일어남. 한 왕조가 특정한 덕에 해당하고 그 덕이 쇠하면, 그것을 이기는 다른 덕을 가진 왕조가 등장함.</li><li><strong>정치철학적 성격:</strong> 단순한 자연철학에 그치지 않고, 왕조 교체의 정당성을 부여한다는 점에서 정치철학이기도 함.</li></ul><h2 id="_2-명가-공손룡" tabindex="-1">2. 명가 (공손룡) <a class="header-anchor" href="#_2-명가-공손룡" aria-label="Permalink to &quot;2. 명가 (공손룡)&quot;">​</a></h2><h3 id="명가의-사회적-배경-및-역할-추정" tabindex="-1">명가의 사회적 배경 및 역할 (추정) <a class="header-anchor" href="#명가의-사회적-배경-및-역할-추정" aria-label="Permalink to &quot;명가의 사회적 배경 및 역할 (추정)&quot;">​</a></h3><ul><li>왕이 정통성을 갖지 못한 시기에 부도덕하다는 비난이 나올 수 있는 일을 정치적으로 포장하여 표현하는 기술을 지닌 집단으로 추정됨.</li><li>외교적 역할도 수행한 것으로 추정됨.</li><li>결국 상대를 속이면서도 거짓이 아닌 듯 포장하는 기술을 사용함.</li></ul><h3 id="백마론-흰말은-말이-아니다" tabindex="-1">백마론 (흰말은 말이 아니다) <a class="header-anchor" href="#백마론-흰말은-말이-아니다" aria-label="Permalink to &quot;백마론 (흰말은 말이 아니다)&quot;">​</a></h3><ul><li><p><strong>논리적 근거:</strong></p><ul><li>&#39;말&#39;은 형체를 명명한 이름임.</li><li>&#39;희다&#39;는 것은 색을 명명한 이름임.</li><li>&#39;흰 말&#39;은 색과 형체를 한꺼번에 명명한 이름이므로, 흰말은 말이 아님.</li></ul></li><li><p><strong>문답 예시:</strong></p><ul><li><em>질문자:</em> 흰말이 있을 때 말이 없다고 할 수는 없다.</li><li><em>공손룡:</em> &#39;말&#39;을 얻으려 할 때는 검은 말도 데려올 수 있지만, &#39;흰말&#39;을 얻으려 할 때는 아무 말이나 데려올 수 없다.</li></ul></li><li><p><strong>핵심 요지:</strong> 집합론적 관점(흰말이 말에 포함된다는 관점)에서 보는 것이 아님. 이름의 지시 범위를 엄격히 구분하여, 대상과 속성을 구분하고자 함. 명칭이 같지 않으면 정치사회적 판단도 혼동될 수 있음.</p></li></ul><h3 id="견백론-단단함과-흼의-분리" tabindex="-1">견백론 (단단함과 흼의 분리) <a class="header-anchor" href="#견백론-단단함과-흼의-분리" aria-label="Permalink to &quot;견백론 (단단함과 흼의 분리)&quot;">​</a></h3><ul><li><p><strong>질문:</strong> 단단함, 흼, 돌 이것이 셋이라고 할 수 있는가? 없다.</p></li><li><p><strong>결론:</strong> 둘이라고 할 수 있음.</p></li><li><p><strong>인식의 한계:</strong> &#39;단단하고 흰 돌&#39;이라는 하나의 사물이 있더라도, 인간의 인식에는 언제나 &#39;흰 돌&#39; 또는 &#39;단단한 돌&#39;로 파악될 뿐 전체가 동시에 감각되는 것은 아님. 눈은 단단함을 알 수 없고 손은 흼을 알 수 없음.</p></li><li><p><strong>성질과 인식:</strong> 그렇다고 단단함과 흼이 없는 것은 아니며, 서로 기능이 달라 대신할 수 없을 뿐임. 흼과 단단함은 사물에 붙어 있는 것처럼 보이지만 인식의 차원에서는 서로 구분됨.</p></li><li><p><strong>요약:</strong> 일상적 차원에서 사물은 하나의 대상으로 말해지지만, 인식의 차원에서는 여러 성질의 결합체로 분석됨.</p></li></ul><h3 id="통변론-관계어의-분석" tabindex="-1">통변론 (관계어의 분석) <a class="header-anchor" href="#통변론-관계어의-분석" aria-label="Permalink to &quot;통변론 (관계어의 분석)&quot;">​</a></h3><ul><li><p><strong>하나와 둘의 관계:</strong> &quot;둘에는 하나가 없다.&quot; 따로 있을 때의 하나와 둘을 이루는 구성요소로 들어간 하나는 다른 상태임. 즉, 관계 속에 들어간 하나와 관계 이전의 고립된 하나는 다름.</p></li><li><p><strong>좌우(左右)의 예시:</strong></p><ul><li><p>둘에 오른쪽이 있는가? 없다.</p></li><li><p>오른쪽은 둘이라고 할 수 있는가? 없다.</p></li><li><p>왼쪽과 오른쪽을 둘이라고 할 수 있는가? 그렇다.</p></li></ul></li><li><p><strong>결론:</strong> 두 사물이 있을 때 그 둘 자체 안에 본래적인 &#39;오른쪽&#39;이라는 성질이 존재하지 않음. 그것은 관계적 명칭이기 때문에 관계를 맺는 상황에 따라 변할 수 있음.</p></li><li><p><strong>명칭의 분류:</strong> 명칭 중에는 사물 자체의 속성을 말하는 것도 있지만, 좌우처럼 관계 속에서만 성립되는 명칭(관계어) 또한 존재함.</p></li></ul><h3 id="지물론-사물과-지시" tabindex="-1">지물론 (사물과 지시) <a class="header-anchor" href="#지물론-사물과-지시" aria-label="Permalink to &quot;지물론 (사물과 지시)&quot;">​</a></h3><ul><li><p><strong>명제:</strong> &quot;사물은 지시 아닌 것이 없지만, 지시는 지시되는 것이 아니다.&quot;</p></li><li><p><strong>지시의 다양성:</strong> 사물은 그것, 저것, 돌 등 여러 방식으로 지시될 수 있음.</p></li><li><p><strong>지시와 대상의 차이:</strong> 지시는 지시되는 대상과는 다름. 지시는 시공간을 넘어서 있고, 대상은 시공간 내에 존재함.</p></li><li><p><strong>존재의 드러남:</strong> 사물은 그저 있는 것처럼 보이지만, 그것을 열린 것으로 받아들이려면 어떤 방식으로든 그것을 구별하고 지목해야 함. 들판의 돌을 지시하지 않으면 그 존재를 드러낼 수 없음.</p></li><li><p><strong>결론:</strong> 지시는 실물처럼 존재하는 것이 아니지만 사물은 실제로 존재하는 것임. 따라서 사물과 이름은 완전히 같은 것도, 완전히 다른 것도 아님.</p></li></ul>',22)])])}const c=i(n,[["render",o]]);export{p as __pageData,c as default};
